{%- set t = states('sensor.homematic_ip_innen_temperatur_luftfeuchtigkeitssensor_temperatur') | float(0) -%}
{%- set p = states('sensor.wohnraum_prognose') | float(0) -%}
{%- set mn = states('input_number.fbh_raum_minimum') | float(22.3) -%}
{%- set nt = is_state('schedule.niedertarif', 'on') -%}
{%- if now().hour >= 12 -%}{%- set pvm = states('sensor.solcast_pv_forecast_prognose_morgen') | float(99) -%}{%- set tm = states('input_number.aussen_prognose_max_morgen') | float(99) -%}{%- else -%}{%- set pvm = states('sensor.solcast_pv_forecast_prognose_heute') | float(99) -%}{%- set tm = states('input_number.aussen_prognose_mittel_6h') | float(99) -%}{%- endif -%}
{%- set nvw = (now().hour >= 21 and now().isoweekday() in [7,1,2,3,4]) or (now().hour < 6 and now().isoweekday() in [1,2,3,4,5]) -%}
{%- set vorladen = nt and nvw and pvm < states('input_number.fbh_vorladen_pv_morgen_unter') | float(0) and tm < states('input_number.fbh_vorladen_tmax_morgen_unter') | float(-99) -%}
{%- set ein = states('input_number.fbh_prognose_ein_unter') | float(22.4) + (0.2 if vorladen else 0) -%}
{%- set aus = states('input_number.fbh_prognose_aus_ueber') | float(22.7) + (0.2 if vorladen else 0) -%}
{%- set pumpe = states.switch.homematic_ip_fbh_pumpe_hk_ii -%}
{%- set on = pumpe is not none and pumpe.state == 'on' -%}
{%- set dur = ((now() - pumpe.last_changed).total_seconds() / 60) if pumpe is not none else 999 -%}
{%- set mlz = states('input_number.fbh_mindestlaufzeit') | float(0) -%}
{%- set mp = states('input_number.fbh_mindestpause') | float(0) -%}
{%- set pvrest = states('sensor.fbh_pv_rest_heute') | float(0) -%}
{%- set sschw = states('input_number.fbh_sonnensperre_ab_kwh') | float(99) -%}
{%- set sonne = is_state('sun.sun', 'above_horizon') -%}
{%- set sperre = sonne and now().hour < 13 and pvrest >= sschw -%}
{%- set aktiv = is_state('input_boolean.fbh_smart_aktiv', 'on') -%}
{%- set hand = not is_state('timer.fbh_hand_pause', 'idle') -%}
{%- set lueften = is_state('binary_sensor.fbh_lueften_aktiv', 'on') -%}
{%- set offen = ['binary_sensor.homematic_ip_turkontakt_hibiscus_tur','binary_sensor.homematic_ip_turkontakt_krauter_tur','binary_sensor.homematic_ip_fensterkontakt_kuche_tur'] | select('is_state','on') | list | count -%}
{%- set nlm = states('input_number.fbh_lueften_nachlauf') | float(45) -%}
{%- set lts = state_attr('input_datetime.fbh_lueften_zuletzt_geschlossen','timestamp') -%}
{%- set m_lueft = 0 if not lueften else (nlm if offen > 0 else [nlm - (now().timestamp() - (lts or 0)) / 60, 0] | max) -%}
{%- set ok = '✅' -%}{%- set no = '❌' -%}{%- set wait = '⏳' -%}
{%- macro z(b) -%}{{ ok if b else no }}{%- endmacro -%}
{%- macro hm(m) -%}{%- set m = [m, 0] | max | int -%}{{ '%d:%02d' | format(m // 60, m % 60) }} h{%- endmacro -%}
## {{ '🟢 FBH-Pumpe läuft' if on else '⚪ FBH-Pumpe steht' }} seit {{ hm(dur) }}
**Entscheid:** {{ states('sensor.fbh_smart_entscheid') }}  
**Modus:** {{ '🟢 LIVE – Smart schaltet die Pumpe' if aktiv else '👁️ Beobachtung – HmIP R1–R8 schalten, Smart rechnet nur mit' }}{{ '  \n⏸️ **Hand-Pause läuft** bis ' ~ (as_datetime(state_attr('timer.fbh_hand_pause','finishes_at')) | as_local).strftime('%H:%M') if hand and state_attr('timer.fbh_hand_pause','finishes_at') else '' }}

{%- set mf = is_state('input_boolean.fbh_mittagsfenster_aktiv', 'on') -%}
{%- set hmn = now().hour * 60 + now().minute -%}
{%- set ms = (state_attr('input_datetime.fbh_mittagsfenster_start', 'timestamp') | int(43200)) // 60 -%}
{%- set me = (state_attr('input_datetime.fbh_mittagsfenster_ende', 'timestamp') | int(57600)) // 60 -%}
{%- set we = now().isoweekday() in [6, 7] -%}
{%- set p21 = states('sensor.wohnraum_prognose_21_uhr') | float(0) -%}
{%- set mfpv = states('input_number.fbh_mittagsfenster_pv_rest_unter') | float(3) -%}
{%- set mfmax = states('input_number.fbh_mittagsfenster_raum_max') | float(22.8) -%}
{%- set sich = (mn - 0.1) | round(1) -%}
{%- if we -%}{%- set w = 4 if hmn >= ms and hmn < me else 1 -%}
{%- elif hmn < 360 or hmn >= 1260 -%}{%- set w = 1 -%}
{%- elif hmn < 420 -%}{%- set w = 2 -%}
{%- elif hmn < ms -%}{%- set w = 3 -%}
{%- elif hmn < me -%}{%- set w = 4 -%}
{%- elif hmn < 1140 -%}{%- set w = 5 -%}
{%- else -%}{%- set w = 6 -%}{%- endif -%}
{%- set lv_s = ok if aktiv else no -%}
{%- set lv_m = ok if aktiv and mf else no -%}
{%- macro hh(m) -%}{{ '%02d:%02d' | format(m // 60, m % 60) }}{%- endmacro -%}
{%- macro mk(i) -%}{{ '▶️' if w == i else '' }}{%- endmacro -%}
{%- if t < 21.8 -%}{%- set zone = '🔴 unter Notregel HmIP (< 21.8 °C)' -%}
{%- elif t < mn - 0.1 -%}{%- set zone = '🟠 Sicherheitsbereich (< ' ~ sich ~ ' °C) → EIN' -%}
{%- elif t < mn -%}{%- set zone = '🟡 knapp unter Minimum (' ~ mn ~ ' °C)' -%}
{%- elif t <= aus -%}{%- set zone = '🟢 im Zielbereich' -%}
{%- else -%}{%- set zone = '🔵 über Prognose-AUS (' ~ aus | round(1) ~ ' °C)' -%}{%- endif %}

### 🌡️ Raum {{ t }} °C – {{ zone }}
<sub>Bereiche: < 21.8 Notregel HmIP · < {{ sich }} Sicherheit EIN · {{ mn }} Minimum · Prognose-Zielband {{ ein | round(2) }}–{{ aus | round(2) }}{{ ' (Vorladen NT +0.2)' if vorladen else '' }} · ≥ {{ mfmax }} Abbruch Mittagsfenster · Prognose in 3 h: {{ p }} °C</sub>

### 🗓️ Tagesablauf {{ 'Wochenende (ganztags Niedertarif)' if we else 'Werktag' }}
| | Zeit | Regel | Temperaturbereich | Live | Bedingung jetzt |
|:-:|---|---|---|:-:|---|
| {{ mk(1) }} | {{ '00:00–24:00' if we else '21:00–06:00' }} | Niedertarif: Prognose-Steuerung{{ ' + Vorladen' if vorladen else '' }} | EIN Prognose < {{ ein | round(2) }} · AUS > {{ aus | round(2) }} | {{ lv_s }} | {{ (z(p < ein) ~ ' EIN (Prognose ' ~ p ~ ' °C) · ' ~ z(p > aus and t >= mn + 0.1) ~ ' AUS') if w == 1 else '' }} |
{%- if not we %}
| {{ mk(2) }} | 06:00–07:00 | Morgen halten: kein neuer Start, laufende Pumpe hält bis 07:00 | nur Sicherheit < {{ sich }} | {{ lv_m }} | {{ ((ok ~ ' Pumpe läuft → halten') if on else (no ~ ' Pumpe steht → kein Start')) if w == 2 else '' }} |
| {{ mk(3) }} | 07:00–{{ hh(ms) }} | HT-Sperre morgens (Sonne/Nachwärme tragen) | nur Sicherheit < {{ sich }} | {{ lv_m }} | {{ (z(t < mn - 0.1) ~ ' Sicherheit (Raum ' ~ t ~ ' °C)') if w == 3 else '' }} |
{%- endif %}
| {{ mk(4) }} | {{ hh(ms) }}–{{ hh(me) }} | Mittagsfenster: Estrich am Stück laden | Prognose 21 Uhr < {{ mn }} · PV-Rest < {{ mfpv }} kWh · Abbruch ≥ {{ mfmax }} | {{ lv_m }} | {{ (z(p21 < mn) ~ ' 21 Uhr ' ~ p21 ~ ' °C · ' ~ z(pvrest < mfpv) ~ ' PV ' ~ pvrest ~ ' kWh · ' ~ z(t < mfmax) ~ ' Raum ' ~ t ~ ' °C') if w == 4 else '' }} |
{%- if not we %}
| {{ mk(5) }} | {{ hh(me) }}–19:00 | HT-Sperre abends | nur Sicherheit < {{ sich }} | {{ lv_m }} | {{ (z(t < mn - 0.1) ~ ' Sicherheit (Raum ' ~ t ~ ' °C)') if w == 5 else '' }} |
| {{ mk(6) }} | 19:00–21:00 | Prognose-Steuerung (2 h vor Niedertarif) | EIN Prognose < {{ ein | round(2) }} · AUS > {{ aus | round(2) }} | {{ lv_s }} | {{ (z(p < ein) ~ ' EIN (Prognose ' ~ p ~ ' °C) · ' ~ z(p > aus and t >= mn + 0.1) ~ ' AUS') if w == 6 else '' }} |
{%- endif %}

{% if not mf -%}<sub>❌ Live = Regel noch nicht aktiv (Schalter «FBH Mittagsfenster aktiv» AUS). Bis dahin gilt in diesen Zeiten die Prognose-Steuerung (Smart-Komfort).</sub>
{%- endif %}

### 🛡️ Gilt immer (Vorrang)
| | Regel | Temperaturbereich | Live | Bedingung jetzt |
|:-:|---|---|:-:|---|
| 🆘 | HmIP-Notregel | Raum < 21.8 | ✅ | {{ z(t < 21.8) }} Raum {{ t }} °C |
| 🛡️ | Sicherheit EIN | Raum < {{ sich }} | {{ lv_s }} | {{ z(t < mn - 0.1) }} Raum {{ t }} °C |
| 🪟 | Lüften: Zustand halten (Hibiscus, Kräuter, Küche + {{ nlm | int }} min) | bis Raum < {{ (mn - 0.5) | round(1) }} | {{ lv_s }} | {{ z(lueften) }} {{ ('offen' if offen > 0 else 'Nachlauf ' ~ hm(m_lueft)) if lueften else 'zu' }} |
| ⏱️ | {{ 'Mindestlaufzeit ' ~ hm(mlz) if on else 'Mindestpause ' ~ hm(mp) }} | – | {{ lv_s }} | {{ z(dur >= (mlz if on else mp)) }} {{ 'läuft' if on else 'steht' }} seit {{ hm(dur) }} |
| ☀️ | Sonnensperre bis 13:00 | PV-Rest ≥ {{ sschw }} kWh und Raum ≥ {{ mn }} | {{ lv_s }} | {{ z(sperre and t >= mn) }} PV-Rest {{ pvrest }} kWh |
| ✋ | Hand-Pause 3 h nach Eingriff | – | {{ lv_s }} | {{ z(hand) }} {{ 'läuft' if hand else 'keine' }} |

{#- Countdown -#}
{%- set ta = states('input_number.aussen_prognose_mittel_6h') | float(t - 10) -%}
{%- set k = states('input_number.fbh_auskuehlfaktor_k') | float(0.01) -%}
{%- set tref = states('input_number.fbh_nachwaerme_referenz_aussen') | float(12) -%}
{%- set fa = [[(ta + 8) / (tref + 8), 0.3] | max, 1] | min -%}
{%- set l6 = states('sensor.heizung_homematic_ip_fbh_pumpe_hk_ii_fbh_laufzeit_6h') | float(0) -%}
{%- set nwf = states('input_number.fbh_nachwaerme_faktor') | float(0) -%}
{%- set rate = k * (t - ta) + (nwf * fa if l6 > 0 else 0) -%}
{%- set rate = [rate, 0.02] | max -%}
{%- if not on %}

### ⏱️ Countdown bis Einschalten
{%- if t < mn - 0.1 %}
**Jetzt** – Sicherheitsregel greift.
{%- else -%}
{%- set m_pause = [mp - dur, 0] | max -%}
{%- set m_prog = ([p - ein, 0] | max) / rate * 60 if p >= ein else 0 -%}
{%- if sperre and t >= mn -%}{%- set m_sperre = (today_at('13:00') - now()).total_seconds() / 60 -%}{%- else -%}{%- set m_sperre = 0 -%}{%- endif -%}
{%- set m = [m_pause, m_prog, m_sperre, m_lueft] | max -%}
{%- set grund = ('Lüften + Nachlauf' ~ (' (Fenster/Tür offen, frühestens)' if offen > 0 else '')) if m == m_lueft and m > 0 else 'Mindestpause' if m == m_pause and m > 0 else ('Sonnensperre bis 13:00' if m == m_sperre and m > 0 else 'Prognose sinkt unter ' ~ ein | round(2) ~ ' °C') -%}
{%- if m <= 0 %}
**Jetzt** – alle Bedingungen für EIN erfüllt{{ '' if aktiv else ' (im Beobachtungsmodus schaltet Smart nicht)' }}.
{%- elif m > 720 %}
**> 12 h** – Raum bleibt laut Prognose warm genug.
{%- else %}
## ≈ {{ hm(m) }} → ca. {{ (now() + timedelta(minutes=m)).strftime('%H:%M') }} Uhr
<sub>Massgebend: {{ grund }} · geschätzt mit Abkühlung ≈ {{ rate | round(2) }} K/h (Aussen {{ ta | round(1) }} °C){{ ' · Niedertarif' if is_state('schedule.niedertarif','on') else '' }}</sub>
{%- endif -%}
{%- endif -%}
{%- else %}

### ⏱️ Restlaufzeit
{%- set m_mlz = [mlz - dur, 0] | max %}
{{ 'Mindestlaufzeit noch **' ~ hm(m_mlz) ~ '** (bis ca. ' ~ (now() + timedelta(minutes=m_mlz)).strftime('%H:%M') ~ ' Uhr), danach entscheidet die Prognose.' if m_mlz > 0 else 'Mindestlaufzeit erfüllt – AUS, sobald Prognose > ' ~ aus | round(2) ~ ' °C oder Sonnensperre greift.' }}
{%- endif %}

{%- set t = states('sensor.homematic_ip_innen_temperatur_luftfeuchtigkeitssensor_temperatur') | float(0) -%}
{%- set H = states('input_number.fbh_vorhalt_stunden') | float(3) -%}
{%- set tr = [[states('sensor.wohnzimmer_homematic_ip_innen_temperatur_luftfeuchtigkeitssensor_wohnraum_trend') | float(0), -0.5] | max, 0.5] | min -%}
{%- set tr = [tr, 0] | max if is_state('binary_sensor.fbh_lueften_aktiv', 'on') else tr -%}
{%- set k = states('input_number.fbh_auskuehlfaktor_k') | float(0.01) -%}
{%- set ta = states('input_number.aussen_prognose_mittel_6h') | float(t - 10) -%}
{%- set s = states('input_number.fbh_sonnenfaktor') | float(0) -%}
{%- set pv = states('sensor.fbh_pv_prognose_vorhalt') | float(0) -%}
{%- set ein = is_state('switch.homematic_ip_fbh_pumpe_hk_ii', 'on') -%}
{%- set hb = states('input_number.fbh_heizbeitrag') | float(0) if ein else 0 -%}
{%- set tref = states('input_number.fbh_nachwaerme_referenz_aussen') | float(12) -%}
{%- set fa = [[(ta + 8) / (tref + 8), 0.3] | max, 1] | min -%}
{%- set l6 = states('sensor.heizung_homematic_ip_fbh_pumpe_hk_ii_fbh_laufzeit_6h') | float(0) -%}
{%- set nw = 0 if ein else states('input_number.fbh_nachwaerme_faktor') | float(0) * ([l6, 6] | min) * fa -%}
{%- macro v(x) -%}{{ ('+' if x >= 0 else '−') ~ '%.2f' | format(x | abs) }} K{%- endmacro -%}
### 🧮 Prognose in {{ H | round(1) }} h – Bausteine
| Baustein | Grundlage | Beitrag |
|---|---|---|
| Raum jetzt | HmIP Innen | **{{ t }} °C** |
| Trend | {{ '%+.2f' | format(tr) }} K/h (60 min, max ±0.5{{ ', Lüften: nur ≥ 0' if is_state('binary_sensor.fbh_lueften_aktiv','on') else '' }}) × {{ H }} h × 0.5 | {{ v(tr * H * 0.5) }} |
| Auskühlung | k {{ k }} × (Raum − Aussen {{ ta | round(1) }} °C) × {{ H }} h | {{ v(- k * (t - ta) * H) }} |
| Sonne | {{ pv | round(2) }} kWh PV (nächste {{ H }} h) × {{ s }} | {{ v(s * pv) }} |
| Heizbeitrag | {{ 'Pumpe EIN' if ein else 'Pumpe AUS → 0' }} | {{ v(hb) }} |
| Nachwärme Estrich | {{ 'Pumpe EIN → 0' if ein else (l6 | round(1) ~ ' h Laufzeit (letzte 6 h) × ' ~ states('input_number.fbh_nachwaerme_faktor') ~ ' × Aussenfaktor ' ~ fa | round(2)) }} | {{ v(nw) }} |
| **Prognose** | Summe | **{{ states('sensor.wohnraum_prognose') }} °C** |

{%- set ta = states('input_number.aussen_prognose_mittel_6h') | float(99) -%}
{%- set th = states('sensor.homematic_ip_aussen_temperatur_luftfeuchtigkeitssensor_temperatur') | float(0) -%}
{%- set t = states('sensor.homematic_ip_innen_temperatur_luftfeuchtigkeitssensor_temperatur') | float(0) -%}
{%- set k = states('input_number.fbh_auskuehlfaktor_k') | float(0) -%}
{%- set band = '> 10 °C' if ta > 10 else ('5–10 °C' if ta >= 5 else ('0–5 °C' if ta >= 0 else '< 0 °C')) -%}
{%- set tref = states('input_number.fbh_nachwaerme_referenz_aussen') | float(12) -%}
{%- set fa = [[(ta + 8) / (tref + 8), 0.3] | max, 1] | min -%}
## 🌡️ Aktueller Aussenbereich: **{{ band }}**
met.no-Mittel 6 h **{{ ta }} °C** · HmIP Unterstand {{ th }} °C · Raum {{ t }} °C

| Modell jetzt | Wert |
|---|---|
| Auskühlfaktor k | {{ k }} K/h/K |
| Auskühlung ohne FBH (Modell) | {{ (k * (t - ta)) | round(2) }} K/h |
| Nachwärme-Aussenfaktor fa | {{ fa | round(2) }} → {{ (states('input_number.fbh_nachwaerme_faktor') | float(0) * fa) | round(3) }} K je h Laufzeit |
| Vorhalt H | {{ states('input_number.fbh_vorhalt_stunden') }} h |
| Modus | {{ '🟢 LIVE' if is_state('input_boolean.fbh_smart_aktiv','on') else '👁️ Beobachtung (HmIP schaltet)' }} |

{%- set ta = states('input_number.aussen_prognose_mittel_6h') | float(99) -%}
{%- set akt = 0 if ta > 10 else (1 if ta >= 5 else (2 if ta >= 0 else 3)) -%}
{%- set rows = [
 ['> 10 °C', '0.008 (vorläufig)', '~0.08–0.1 K/h', '2–3 h', '0.1 K', '3 h', '16./17., 17./18., 18./19.11.'],
 ['5–10 °C', '0.008', '~0.1–0.12 K/h', '~4 h', '~0.08 K', '3 h (Kandidat 5 h)', '20./21.11.'],
 ['0–5 °C', 'offen (0.008)', '14.11. abends ~0.2 K/h', 'offen (> 4 h?)', '0.1 × fa', 'offen', 'fehlt'],
 ['< 0 °C', 'offen', 'offen', 'offen', '0.03 K', 'offen', 'fehlt']
] -%}
### 📋 Prognosetabelle je Aussenbereich (Lernphase)
<sub>Aussen = met.no-Mittel 6 h · Zielband fix (Minimum 22.3, EIN 22.4, AUS 22.5 °C) · ▶ = aktueller Bereich · nachgeführt nach jeder Nachtauswertung</sub>

| | Aussen | k (K/h/K) | Auskühlung ohne FBH | Totzeit FBH | Nachwärme je h Laufzeit | Vorhalt EIN | Messnächte |
|:-:|---|---|---|---|---|---|---|
{% for r in rows -%}
| {{ '▶' if loop.index0 == akt else '' }} | {{ '**' ~ r[0] ~ '**' if loop.index0 == akt else r[0] }} | {{ r[1] }} | {{ r[2] }} | {{ r[3] }} | {{ r[4] }} | {{ r[5] }} | {{ r[6] }} |
{% endfor %}
